package com.rikkeibank.account.service;import com.rikkeibank.account.domain.*;import com.rikkeibank.account.repo.*;import com.rikkeibank.common.api.BusinessException;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AccountServiceTest{@Test void rejectsDebitAboveBalance(){AccountRepository accounts=mock(AccountRepository.class);AccountTypeRepository types=mock(AccountTypeRepository.class);LedgerOperationRepository operations=mock(LedgerOperationRepository.class);AccountService service=new AccountService(accounts,types,operations);UUID accountId=UUID.randomUUID(),customerId=UUID.randomUUID(),operationId=UUID.randomUUID();Account account=new Account("1001000000000001",customerId,UUID.randomUUID(),new BigDecimal("100.00"));when(operations.existsByOperationIdAndKind(operationId,"DEBIT")).thenReturn(false);when(accounts.lock(accountId)).thenReturn(Optional.of(account));assertThatThrownBy(()->service.debit(operationId,accountId,customerId,new BigDecimal("100.01"))).isInstanceOf(BusinessException.class).hasMessageContaining("Insufficient");verify(operations,never()).save(any());}
@Test void repeatedDebitIsIdempotent(){AccountRepository accounts=mock(AccountRepository.class);AccountService service=new AccountService(accounts,mock(AccountTypeRepository.class),mock(LedgerOperationRepository.class));UUID accountId=UUID.randomUUID(),customerId=UUID.randomUUID(),op=UUID.randomUUID();Account a=new Account("1001000000000002",customerId,UUID.randomUUID(),BigDecimal.TEN);LedgerOperationRepository operations=mock(LedgerOperationRepository.class);service=new AccountService(accounts,mock(AccountTypeRepository.class),operations);when(operations.existsByOperationIdAndKind(op,"DEBIT")).thenReturn(true);when(accounts.findById(accountId)).thenReturn(Optional.of(a));assertThat(service.debit(op,accountId,customerId,BigDecimal.ONE).getBalance()).isEqualByComparingTo("10.00");verify(accounts,never()).lock(any());}}
